"use client";
import Component from "../smoothui/NotificationBadge";
import { useState } from "react";
import { BellIcon } from "@phosphor-icons/react";
import { DemoFrame } from "../shared/DemoFrame";
export default function Demo() {
  const [count, setCount] = useState(3);
  return (
    <DemoFrame hint={`${count} unread notifications`}>
      <div className="flex items-center gap-8">
        <Component count={count} ping>
          <button
            className="grid size-16 place-items-center rounded-2xl border bg-background"
            onClick={() => setCount(0)}
            aria-label="Read all notifications"
          >
            <BellIcon size={28} />
          </button>
        </Component>
        <div>
          <p className="font-medium">A little update.</p>
          <p className="mt-1 text-xs text-muted-foreground">Tap the bell to mark all as read.</p>
        </div>
      </div>
      <button className="demo-action" onClick={() => setCount(count + 1)}>
        Add notification
      </button>
    </DemoFrame>
  );
}

/** Example and adapters: Copyright (c) 2026 NikroZorkin. MIT; licenses/elements.txt. */
import type { ReactNode } from "react";

/** Layout for this example only. The component itself has no catalog dependency. */
export function DemoFrame({
  children,
  className = "",
  hint,
}: {
  children: ReactNode;
  className?: string;
  hint?: string;
}) {
  return (
    <div
      className={`relative flex min-h-[420px] w-full flex-col items-center justify-center gap-7 overflow-hidden p-8 ${className}`}
    >
      {children}
      {hint && (
        <p className="text-center text-xs text-muted-foreground" role="status">
          {hint}
        </p>
      )}
    </div>
  );
}

