          className="inline-block"
          exit={{ opacity: 0, y: direction * -12 }}
          initial={{ opacity: 0, y: direction * 12 }}
          key={value}
          transition={{ bounce: 0.1, duration: 0.3, type: "spring" as const }}
        >
          {displayValue}
        </motion.span>
      </AnimatePresence>
    </span>
